:root {
  --ink: #24364a;
  --paper: #fffdf7;
  --sky: #4d8fc7;
}

.chime-tag {
  width: 440px;
  box-sizing: border-box;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.tag-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--sky);
  color: var(--paper);
}

.tag-header h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1.1;
}

.status {
  padding: 4px 8px;
  border: 1px solid var(--paper);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.details {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 16px;
}

.details p {
  margin: 0;
  font-size: 14px;
  line-height: 1.4;
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  padding: 9px 16px;
  border-top: 1px solid var(--ink);
  font-size: 12px;
  font-weight: 700;
}
